   const body = pm.response.json();
   pm.environment.set("last_sha", body.sha);

   pm.test("status is 200", () => {
     pm.response.to.have.status(200);
   });

   pm.test("success is true", () => {
     pm.expect(body.success).to.eql(true);
   });

   pm.test("sha is a 40-char git hash", () => {
     pm.expect(body.sha).to.match(/^[0-9a-f]{40}$/);
   });

   pm.test("requestId is present", () => {
     pm.expect(body.requestId).to.be.a("string").and.not.empty;
   });

   pm.test("responds in under 10s", () => {
     pm.expect(pm.response.responseTime).to.be.below(10000);
   });

   const body = pm.response.json();
   pm.environment.set("last_sha", body.sha);
   const decoded = JSON.parse(
     CryptoJS.enc.Base64.parse(body.content.replace(/\n/g, "")).toString(CryptoJS.enc.Utf8)
   );

   pm.test("status is 200", () => {
     pm.response.to.have.status(200);
   });

   pm.test("file sha matches the sha the function returned", () => {
     pm.expect(body.sha).to.eql(pm.environment.get("last_sha"));
   });

   pm.test("content is the exact data we sent", () => {
     pm.expect(decoded.apiTest).to.eql(true);
     pm.expect(decoded.runAt).to.eql(pm.environment.get("run_at"));
   });

   pm.test("unicode survived the round trip", () => {
     pm.expect(decoded.label).to.eql("héllo ⚽");
   });
